#define ALGOERROR_CABINET_CONSTRUCTOR_ERROR_CABINET_STATE                 ERROR_CODE(ALGOMOD_CABINET_CONSTRUCTOR, 112) // 屏体状态异常，死灯过多或部分数据组不可控，请检查箱体
#define ALGOERROR_CABINET_CONSTRUCTOR_ERROR_CANNOT_CONSTRUCT              ERROR_CODE(ALGOMOD_CABINET_CONSTRUCTOR, 113) // 屏体数据组不可控(识别到的标识码不等于已发送标识码)，无法自动构造。请检查屏体状态
#define ALGOERROR_CABINET_CONSTRUCTOR_ERROR_DECODE_MARKER                 ERROR_CODE(ALGOMOD_CABINET_CONSTRUCTOR, 114) // 检出标识码数量过少，检查屏体状态或联系算法
#define ALGOERROR_CABINET_CONSTRUCTOR_ERROR_EMPTY_RESULT                  ERROR_CODE(ALGOMOD_CABINET_CONSTRUCTOR, 115) // 检测结果为空
#define ALGOERROR_CABINET_CONSTRUCTOR_ERROR_WRITE_DATA					  ERROR_CODE(ALGOMOD_CABINET_CONSTRUCTOR, 116) // 写入数据错误
#define ALGOERROR_CABINET_CONSTRUCTOR_ERROR_MARKER_NUM					  ERROR_CODE(ALGOMOD_CABINET_CONSTRUCTOR, 118) // 无法自动构造, 检测到的标识码数量错误，检测到的标识码数量小于输入标识码数量，屏体标识码区域可能存在遮挡或屏体存在未被点亮的模组
#define ALGOERROR_CABINET_CONSTRUCTOR_ERROR_MARKER_ORDER				  ERROR_CODE(ALGOMOD_CABINET_CONSTRUCTOR, 119) // 无法自动构造, 检测到的标识码索引号错误，屏体所有模组均被点亮，但存在重复单元，请检查箱体每个模组是否正常点亮
#define ALGOERROR_CABINET_CONSTRUCTOR_ERROR_DISPLAY_NOT_EQUAL_INPUT		  ERROR_CODE(ALGOMOD_CABINET_CONSTRUCTOR, 120) // 显示画面不一致，当前屏体显示画面与给定pattern不相同。请检查，是否屏体显示状态异常，或输入的pattern画面不正确






